"""The first line of a generated file: it says the file is generated and where hand-written code goes instead.

A coding agent that opens a generated file learns from this line not to edit it; the record
``.besser_generated.json`` beside the output lists every generated file. The line is added to
the output that :mod:`besser.generators.regeneration` records (``besser generate``,
``regenerate`` and ``build``), and only to files whose language has line comments it knows.
"""

from __future__ import annotations

import os

MARKER = "Generated by BESSER"
_ADVICE = "edit the model, not this file"
# A template that writes its own header names BESSER near the top: it is not given a second one.
_OWN_HEADER_LINES = 5

# File extension -> how a comment starts and ends in that language.
_COMMENTS: dict[str, tuple[str, str]] = {
    **dict.fromkeys((".py", ".pyi", ".rb", ".sh", ".bash", ".yml", ".yaml", ".toml", ".tf", ".r", ".graphql"),
                    ("# ", "")),
    **dict.fromkeys((".js", ".jsx", ".mjs", ".cjs", ".ts", ".tsx", ".java", ".kt", ".kts", ".go", ".rs", ".cs",
                     ".dart", ".swift", ".scala", ".c", ".h", ".cpp", ".hpp", ".proto", ".scss"), ("// ", "")),
    ".sql": ("-- ", ""),
    ".css": ("/* ", " */"),
}


def header_text(extension_file: str | None) -> str:
    """The header's words, naming ``extension_file`` (a generator's hook file) as the place for custom code."""
    where = f"in {extension_file}" if extension_file else "outside this folder"
    return f"{MARKER}: {_ADVICE}. Custom code goes {where}."


def _keeps_first_line(line: str) -> bool:
    """A shebang, or a Python encoding declaration, must stay the first line."""
    return line.startswith("#!") and not line.startswith("#![") or line.startswith("# -*-")


def mark_generated(files: dict[str, bytes], extension_file: str | None = None) -> dict[str, bytes]:
    """``files`` (path -> content) with the header added to each text file of a known language.

    A file that already names BESSER at its top is left as it is, so marking twice changes nothing.
    """
    text = header_text(extension_file)
    marked = {}
    for rel, content in files.items():
        comment = _COMMENTS.get(os.path.splitext(rel)[1].lower())
        try:
            source = content.decode("utf-8") if comment else None
        except UnicodeDecodeError:
            source = None
        if source is None or MARKER in "".join(source.splitlines(keepends=True)[:_OWN_HEADER_LINES]):
            marked[rel] = content
            continue
        newline = "\r\n" if "\r\n" in source else "\n"
        header = f"{comment[0]}{text}{comment[1]}{newline}"
        first, _, rest = source.partition("\n")
        if _keeps_first_line(first):
            marked[rel] = f"{first}\n{header}{rest}".encode("utf-8")
        else:
            marked[rel] = (header + source).encode("utf-8")
    return marked


def without_header(content: bytes) -> bytes:
    """``content`` without the header :func:`mark_generated` adds, to compare with output generated before it."""
    lines = content.split(b"\n")
    for index in range(min(2, len(lines))):
        if f"{MARKER}: {_ADVICE}".encode("utf-8") in lines[index]:
            return b"\n".join(lines[:index] + lines[index + 1:])
    return content
